value.Fecha de Registro:
==IFERROR(
    IF(
        ISNUMBER(SEARCH("GMT"; "{{ $json.date }}")); 
        DATE(
            MID("{{ $json.date }}"; 12; 4); 
            SWITCH(MID("{{ $json.date }}"; 5; 3); 
                "Jan"; 1; "Feb"; 2; "Mar"; 3; "Apr"; 4; "May"; 5; "Jun"; 6; 
                "Jul"; 7; "Aug"; 8; "Sep"; 9; "Oct"; 10; "Nov"; 11; "Dec"; 12
            ); 
            MID("{{ $json.date }}"; 9; 2)
        ) + TIMEVALUE(MID("{{ $json.date }}"; 18; 8)); 
        DATE(
            MID("{{ $json.date }}"; 1; 4); 
            MID("{{ $json.date }}"; 6; 2); 
            MID("{{ $json.date }}"; 9; 2)
        ) + TIMEVALUE(MID("{{ $json.date }}"; 12; 8))
    ); 
    "Sin Fecha"
)

